CREATE TEMP TRIGGER IF NOT EXISTS workspace_outbox_tasks_insert AFTER INSERT ON main.tasks BEGIN SELECT cortex_workspace_invalidate('runtime',NEW.id) WHERE EXISTS (SELECT 1 FROM workspace_executions WHERE runtime_task_id=NEW.id); END;
CREATE TEMP TRIGGER IF NOT EXISTS workspace_outbox_tasks_update AFTER UPDATE ON main.tasks BEGIN SELECT cortex_workspace_invalidate('runtime',NEW.id) WHERE EXISTS (SELECT 1 FROM workspace_executions WHERE runtime_task_id=NEW.id);SELECT cortex_workspace_invalidate('runtime',OLD.id) WHERE OLD.id IS NOT NEW.id AND EXISTS (SELECT 1 FROM workspace_executions WHERE runtime_task_id=OLD.id); END;
